/* Model Linguistic Coverage Database Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"FLORES-200": "200 languages — Meta AI", "XTREME": "cross-lingual transfer evaluation — Google Research", "XNLI": "cross-lingual natural language inference — Facebook AI", "PAWS-X": "paraphrase adversaries, cross-lingual — Google Research", "TyDi QA": "typologically diverse question answering — Google Research", "XQuAD": "cross-lingual question answering data — DeepMind", "-200": "The coverage surname: the number of languages.", "-R": "The revision surname: the benchmark, revisited.", "v2": "The version surname.", "multilingual-": "The prefix-surname of the coverage era."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'FLORES-200';
console.log(lookup(q));

